const lines=a=>a.join("\n");
const header=spec=>[
"# Generated by Belgium Data Desk",
"# Validation scaffold; inspect publisher fields before production use.",
"# Expected relationship: "+spec.expected,
"# Left: "+spec.leftUrl,
"# Right: "+spec.rightUrl,
""
];
export function pythonValidationRecipe(spec,plan){
  if(!spec)return"# No validation-pack entry for this pair.";
  const h=header(spec);
  if(spec.id==="statbel-sector-pop-geometry")return lines([...h,
"import pandas as pd",
"import geopandas as gpd",
"POPULATION_PATH = 'population_2025.xlsx'",
"GEOMETRY_PATH = 'statistical_sectors_2025.geojson'",
"pop = pd.read_excel(POPULATION_PATH)",
"geo = gpd.read_file(GEOMETRY_PATH)",
"lk = next(c for c in pop.columns if 'sector' in c.lower())",
"rk = next(c for c in geo.columns if 'sector' in c.lower() or 'cd_sector' in c.lower())",
"pop[lk] = pop[lk].astype(str).str.strip()",
"geo[rk] = geo[rk].astype(str).str.strip()",
"m = pop.merge(geo[[rk]], left_on=lk, right_on=rk, how='left', indicator=True, validate='1:1')",
"print({'rows':len(m),'matched':int((m['_merge']=='both').sum()),'unmatched':int((m['_merge']!='both').sum())})"
]);
  if(spec.id==="opgroeien-capacity-coverage")return lines([...h,
"import pandas as pd",
"CAPACITY_PATH = 'capacity.xlsx'",
"COVERAGE_PATH = 'coverage.xlsx'",
"cap = pd.read_excel(CAPACITY_PATH)",
"cov = pd.read_excel(COVERAGE_PATH)",
"# Map these four names to the actual workbook headings after inspection.",
"GEO, PLACES, CHILDREN, RATIO = 'geography', 'places', 'children aged 0-3', 'places per 100 children'",
"cap2 = cap.groupby(GEO, as_index=False)[PLACES].sum()",
"m = cov.merge(cap2, on=GEO, how='left', validate='1:1')",
"m['recomputed'] = 100 * m[PLACES] / m[CHILDREN]",
"m['abs_error'] = (m['recomputed'] - m[RATIO]).abs()",
"print(m['abs_error'].describe())"
]);
  if(spec.id==="nbb-reference-document")return lines([...h,
"import os, requests",
"API_BASE = os.environ['NBB_API_BASE']",
"SUBSCRIPTION_KEY = os.environ['NBB_SUBSCRIPTION_KEY']",
"ENTERPRISE_NUMBER = os.environ['ENTERPRISE_NUMBER']",
"headers = {'Ocp-Apim-Subscription-Key': SUBSCRIPTION_KEY}",
"r = requests.get(f'{API_BASE}/legalEntity/{ENTERPRISE_NUMBER}/references', headers=headers, timeout=30)",
"r.raise_for_status()",
"payload = r.json()",
"print('reference response received', type(payload).__name__)",
"# Select a published deposit reference and call the document endpoint documented for your subscription."
]);
  if(spec.id==="delijn-static-realtime")return lines([...h,
"import io, os, zipfile, requests, pandas as pd",
"from google.transit import gtfs_realtime_pb2",
"STATIC_ZIP = 'de_lijn_gtfs.zip'",
"REALTIME_URL = os.environ['DELIJN_GTFS_RT_URL']",
"API_KEY = os.environ['DELIJN_API_KEY']",
"with zipfile.ZipFile(STATIC_ZIP) as z:",
"    trips = pd.read_csv(z.open('trips.txt'), dtype=str)",
"feed = gtfs_realtime_pb2.FeedMessage()",
"r = requests.get(REALTIME_URL, headers={'Ocp-Apim-Subscription-Key':API_KEY}, timeout=30)",
"r.raise_for_status(); feed.ParseFromString(r.content)",
"rt_trip_ids = {e.trip_update.trip.trip_id for e in feed.entity if e.HasField('trip_update') and e.trip_update.trip.trip_id}",
"static_ids = set(trips['trip_id'].dropna())",
"print({'rt_trip_ids':len(rt_trip_ids),'matched':len(rt_trip_ids & static_ids),'unmatched':len(rt_trip_ids-static_ids)})"
]);
  if(spec.id==="onderwijs-institution-location")return lines([...h,
"import requests, pandas as pd",
"institutions = requests.get("+JSON.stringify(spec.leftUrl)+", timeout=30).json()",
"locations = requests.get("+JSON.stringify(spec.rightUrl)+", timeout=30).json()",
"print(type(institutions).__name__, type(locations).__name__)",
"# Resolve the published institution identifier in both responses; assert parent uniqueness and 1:n location fan-out."
]);
  if(spec.id==="waterinfo-station-series")return lines([...h,
"import requests",
"MAP = "+JSON.stringify(spec.leftUrl),
"SERIES = "+JSON.stringify(spec.rightUrl),
"meta = requests.get(MAP, params={'f':'pjson'}, timeout=30).json()",
"layer = next((x for x in meta['layers'] if 'afvoer' in x['name'].lower() or 'debiet' in x['name'].lower()), meta['layers'][0])",
"stations = requests.get(MAP+'/'+str(layer['id'])+'/query', params={'where':'1=1','outFields':'*','returnGeometry':'false','resultRecordCount':100,'f':'json'}, timeout=30).json()",
"series = requests.get(SERIES, timeout=30).json()",
"print('station features', len(stations.get('features',[])), 'series payload', type(series).__name__)",
"# Resolve station_id/station_no on both sides, then count matched keys, nulls, duplicates and observed fan-out."
]);
  if(spec.id==="basis-address-parcel")return lines([...h,
"import os, requests",
"PARCEL_ID = os.environ['PARCEL_OBJECT_ID']",
"parcel_url = "+JSON.stringify(spec.rightUrl)+".replace('{objectId}', PARCEL_ID)",
"r = requests.get(parcel_url, timeout=30); r.raise_for_status()",
"parcel = r.json()",
"print(parcel)",
"# Follow explicit linked address IDs/URIs from the parcel response; do not match on address text."
]);
  if(spec.id==="fluvius-sector-statbel-geometry")return lines([...h,
"import pandas as pd, requests",
"rows = requests.get("+JSON.stringify(spec.leftUrl)+", timeout=30).json()['results']",
"df = pd.DataFrame(rows)",
"key = next(c for c in df.columns if 'stat' in c.lower() and 'sector' in c.lower())",
"df[key] = df[key].astype(str).str.strip()",
"print({'rows':len(df),'unique_sector_keys':int(df[key].nunique()),'null_keys':int(df[key].isna().sum())})",
"# Load the chosen Statbel sector geometry locally, verify its boundary vintage, then perform the n:1 sector-key merge."
]);
  return lines([...h,"# Follow the relationship contract shown in the Data Desk planner."]);
}
export function sqlValidationRecipe(spec,plan){
  const expected=spec?.expected||plan?.label||"validate documented relationship";
  const keyHint=plan?.key||"publisher-declared join key";
  return lines([
"-- Validation template generated by Belgium Data Desk",
"-- Expected: "+expected,
"-- Key/alignment hint: "+keyHint,
"-- Replace <LEFT_KEY_COLUMN> and <RIGHT_KEY_COLUMN> only after inspecting the publisher schema.",
"WITH l AS (",
"  SELECT TRIM(CAST(<LEFT_KEY_COLUMN> AS VARCHAR)) AS join_key, COUNT(*) AS n",
"  FROM left_dataset",
"  GROUP BY 1",
"), r AS (",
"  SELECT TRIM(CAST(<RIGHT_KEY_COLUMN> AS VARCHAR)) AS join_key, COUNT(*) AS n",
"  FROM right_dataset",
"  GROUP BY 1",
"), keys AS (",
"  SELECT COALESCE(l.join_key,r.join_key) AS join_key, l.n AS left_n, r.n AS right_n",
"  FROM l FULL OUTER JOIN r USING (join_key)",
")",
"SELECT",
"  COUNT(*) FILTER (WHERE left_n IS NOT NULL AND right_n IS NOT NULL) AS matched_unique_keys,",
"  COUNT(*) FILTER (WHERE left_n IS NOT NULL AND right_n IS NULL) AS left_unmatched_unique_keys,",
"  COUNT(*) FILTER (WHERE left_n IS NULL AND right_n IS NOT NULL) AS right_unmatched_unique_keys,",
"  MAX(COALESCE(left_n,0)) AS max_left_fanout,",
"  MAX(COALESCE(right_n,0)) AS max_right_fanout",
"FROM keys;",
"",
"-- Separately assert null-key rate and the relationship-specific version/geography contract."
  ]);
}
export function validationRecipeKind(spec){
  if(!spec)return"none";
  if(spec.tier==="live"||spec.tier==="parameterized-live")return"live + reproducible scaffold";
  if(spec.tier==="hybrid")return"live source probe + file-side scaffold";
  if(spec.tier==="credentials")return"credentialed scaffold";
  return"file-assisted scaffold";
}
